using UnityEngine;
using UnityEditor;

public class FixTransparency
{
    public static string Main()
    {
        var sb = new System.Text.StringBuilder();

        string[] paths = { "Assets/Herbal/JamuIcon.png", "Assets/Herbal/SpiceIcon.png" };
        foreach (var path in paths)
        {
            TextureImporter ti = AssetImporter.GetAtPath(path) as TextureImporter;
            if (ti != null) 
            {
                ti.alphaIsTransparency = true;
                ti.SaveAndReimport();
                sb.AppendLine("[OK] Alpha transparency diaktifkan untuk: " + path);
            }
        }

        AssetDatabase.Refresh();
        return sb.ToString();
    }
}
